#pragma once
// Included by the native Capella fixture after its sync-fault declarations.
#ifdef NANO_SYNC_FAULT
static int bls_sync_writer(const fs::path& directory,bool exit=false){
 auto admit=[&](CapellaDurableReactor& reactor,const Bytes& wire){return exit?reactor.voluntary_exit_ssz(wire):reactor.bls_change_ssz(wire);};
 const auto bundle=load(directory/"bundle.json");const auto profile=bundle.at("profile").get<std::string>();const auto rules=load_capella_fork_profile(profile,sha256(Bytes(profile.begin(),profile.end())),1024*1024);
 Genesis genesis;genesis.chain_id=rules.transition.chain_id;genesis.consensus="beacon";genesis.evm_revision=EvmRevision::Shanghai;genesis.block=Block::from_json(bundle.at("genesis"));genesis.state=State::from_json(bundle.at("alloc"));
 ChainStore witness(directory/"witness");Blockchain owner(directory/"db",genesis);CapellaDurableReactor reactor(owner,rules,crash_limits,witness);reactor.tick(bundle.at("time").get<uint64_t>());const auto before=reactor.current();const auto wire=unhex(bundle.at("wire").get<std::string>());const auto& disk=owner.store();const auto old=disk.fork_checkpoint(genesis.chain_id,genesis.block.header.hash(),crash_limits.envelope_bytes,before.token);
 std::string next;
 {ChainStore reference(directory/"reference");reference.bind_chain(genesis.chain_id,genesis.block.header.hash(),"capella-bls-reference");reference.commit(genesis.block,genesis.state,{});CapellaDurableReactor candidate(reference,genesis.chain_id,genesis.block.header.hash(),rules,crash_limits,*before.state);check(admit(candidate,wire),"reference operation admission failed");next=reference.fork_checkpoint(genesis.chain_id,genesis.block.header.hash(),crash_limits.envelope_bytes)->snapshot;}
 save(directory/"expected.json",Json{{"old",old->snapshot},{"new",next},{"sequence",before.token.sequence},{"state",capella_store_snapshot(*before.state,rules,crash_limits)}});
 const bool fault_witness=bundle.at("faultWitness");fs::path wal;for(const auto& entry:fs::directory_iterator(directory/(fault_witness?"witness":"db")))if(entry.path().extension()==".log"&&(wal.empty()||entry.path().filename()>wal.filename()))wal=entry.path();check(!wal.empty(),"operation sync WAL missing");const auto offset=fs::file_size(wal);
 Rpc rpc(owner);nano_test_arm_sync_fault(wal.c_str());bool failed=false;try{admit(reactor,wire);}catch(const std::runtime_error&){failed=true;}check(failed&&nano_test_sync_failures()>0,"operation sync fault not reached");
 unsigned blocked=0;auto refuse=[&](auto action){try{action();}catch(const std::runtime_error&){++blocked;}};refuse([&]{reactor.current();});refuse([&]{reactor.tick(bundle.at("time").get<uint64_t>());});refuse([&]{admit(reactor,wire);});refuse([&]{disk.latest();});refuse([&]{disk.fork_checkpoint(genesis.chain_id,genesis.block.header.hash(),crash_limits.envelope_bytes);});refuse([&]{owner.tip();});refuse([&]{owner.state();});refuse([&]{owner.finalized_block();});check(blocked==(fault_witness?6:8),"uncertain operation admission left owner accessible");check(rpc.handle(Json{{"jsonrpc","2.0"},{"id",1},{"method","eth_blockNumber"},{"params",Json::array()}}).contains("error"),"uncertain operation owner served RPC");
 std::cout<<Json{{"wal",wal.filename().string()},{"before",offset},{"after",fs::file_size(wal)},{"blocked",blocked}}.dump()<<std::endl;_exit(0);
}
static void qualify_bls_sync(const std::string& executable,const CapellaForkBlockRules& rules,const std::string& initial,const Block& block,const State& state,uint64_t time,const Bytes& wire,bool exit=false){
 auto admit=[&](CapellaDurableReactor& reactor,const Bytes& wire){return exit?reactor.voluntary_exit_ssz(wire):reactor.bls_change_ssz(wire);};
 auto pending=[&](CapellaDurableReactor& reactor){return exit?reactor.pending_exits().size():reactor.pending_bls_changes().size();};
 Genesis genesis;genesis.chain_id=rules.transition.chain_id;genesis.consensus="beacon";genesis.evm_revision=EvmRevision::Shanghai;genesis.block=block;genesis.state=state;
 for(unsigned disposition=0;disposition<4;++disposition){const bool fault_witness=disposition>=2,lose=disposition%2;Temp directory;
  {ChainStore witness(directory/"witness");Blockchain owner(directory/"db",genesis);auto first=capella_store_from_snapshot(initial,sha256(Bytes(initial.begin(),initial.end())),rules,crash_limits);CapellaDurableReactor reactor(owner,rules,crash_limits,std::move(first),{},&witness);}
  save(directory/"bundle.json",Json{{"profile",capella_fork_profile(rules).dump()},{"genesis",block.to_json(true)},{"alloc",state.to_json()},{"time",time},{"wire",hex(wire)},{"faultWitness",fault_witness}});
  const auto result=success(run({executable,exit?"--exit-sync-writer":"--bls-sync-writer",directory.path.string()}));const auto wal=directory/(fault_witness?"witness":"db")/result.at("wal").get<std::string>();check(fs::file_size(wal)==result.at("after").get<uint64_t>()&&result.at("after")>result.at("before"),"operation sync WAL suffix missing");
  if(lose){const int fd=open(wal.c_str(),O_WRONLY);check(fd>=0,"open owned operation WAL");const bool ok=ftruncate(fd,result.at("before").get<uint64_t>())==0&&fsync(fd)==0;close(fd);check(ok,"truncate owned operation WAL");}
  const auto expected=load(directory/"expected.json");ChainStore witness(directory/"witness");Blockchain owner(directory/"db",genesis);const auto& disk=owner.store();const auto record=disk.fork_checkpoint(genesis.chain_id,block.header.hash(),crash_limits.envelope_bytes);const bool primary_new=!fault_witness&&!lose;
  check(record&&record->snapshot==expected.at(primary_new?"new":"old").get<std::string>()&&record->token.sequence==expected.at("sequence").get<uint64_t>()+unsigned(primary_new),"mixed operation checkpoint before recovery");
  auto resumed=std::make_unique<CapellaDurableReactor>(owner,rules,crash_limits,witness);const bool recovered_new=!(fault_witness&&lose);const auto current=resumed->current();check(pending(*resumed)==size_t(recovered_new),"witness operation recovery lost or invented admission");check(capella_store_snapshot(*current.state,rules,crash_limits)==expected.at("state").get<std::string>(),"operation recovery changed consensus state");
  const auto head_pin=capella_fork_head(*current.state,rules);const auto& head=*head_pin;check(owner.tip().header.hash()==head.execution_block.header.hash()&&owner.state().root()==head.execution_state.root(),"operation recovery owner mismatch");check(admit(*resumed,wire),"operation resubmission failed");const auto completed=resumed->current().token;check(completed.sequence==expected.at("sequence").get<uint64_t>()+1&&disk.fork_checkpoint(genesis.chain_id,block.header.hash(),crash_limits.envelope_bytes,completed)->snapshot==expected.at("new").get<std::string>(),"operation recovery resubmission changed candidate");check(admit(*resumed,wire)&&resumed->current().token==completed,"operation recovery duplicate republished");
  resumed.reset();resumed=std::make_unique<CapellaDurableReactor>(owner,rules,crash_limits,witness);check(resumed->current().token==completed&&pending(*resumed)==1,"operation recovered checkpoint not restart-stable");if(exit)check(encode_consensus_voluntary_exit_ssz(resumed->pending_exits().front())==wire,"recovered exit bytes changed");Rpc rpc(owner);check(!rpc.handle(Json{{"jsonrpc","2.0"},{"id",1},{"method","eth_blockNumber"},{"params",Json::array()}}).contains("error"),"operation recovered owner RPC unavailable");
  std::cout<<Json{{"scenario",exit?"capella-exit-sync-recovery":"capella-bls-sync-recovery"},{"faultWitness",fault_witness},{"lostSuffix",lose},{"blockedOperations",result.at("blocked")},{"recoveredPendingBeforeResubmit",recovered_new},{"resubmissionIdempotent",true},{"consensusStateUnchanged",true},{"physicalPowerLoss",false}}.dump()<<std::endl;
 }
}
#endif
